#include <bits/stdc++.h>
using namespace std;struct E{int f,t,a;vector<int>in,out;int c,H;vector<int>mi;};struct N{int p;vector<int>r;int parent,edge;bool live;};
int main(int ac,char**av){ifstream f(av[1]);int m,np,ne,ni,ng,Qcap;f>>m>>np>>ne>>ni>>ng>>Qcap;int d=m+5;vector<int>initial(ni);for(auto&x:initial)f>>x;vector<vector<vector<int>>>goals(np);for(int i=0,p;i<ng;i++){f>>p;vector<int>r(d);for(auto&x:r)f>>x;goals[p].push_back(r);}vector<E>es(ne);vector<vector<int>>adj(np);for(int i=0;i<ne;i++){auto&e=es[i];f>>e.f>>e.t>>e.a;e.in.resize(m);e.out.resize(m);e.mi.resize(5);for(auto&x:e.in)f>>x;for(auto&x:e.out)f>>x;f>>e.c>>e.H;for(auto&x:e.mi)f>>x;adj[e.f].push_back(i);}assert(f);int cap=ac>2?stoi(av[2]):3;size_t limit=ac>3?stoull(av[3]):1000000;vector<N>nodes;vector<vector<int>>basis(np);size_t retired=0,comparisons=0;int hit=-1;auto le=[&](const vector<int>&a,const vector<int>&b){comparisons++;for(int i=0;i<d;i++)if(a[i]>b[i])return false;return true;};auto add=[&](int p,vector<int>r,int par,int ei){auto&v=basis[p];for(int id:v)if(nodes[id].live&&le(r,nodes[id].r))return;for(int id:v)if(nodes[id].live&&le(nodes[id].r,r)){nodes[id].live=false;retired++;}if(v.size()>32){vector<int>w;for(int id:v)if(nodes[id].live)w.push_back(id);v.swap(w);}int id=nodes.size();nodes.push_back({p,r,par,ei,true});v.push_back(id);for(auto&g:goals[p])if(le(g,r))hit=id;};for(int p:initial)add(p,vector<int>(d),-1,-1);size_t next=nodes.size();int depth=0;for(size_t k=0;k<nodes.size()&&hit<0;k++){if(k==next){depth++;next=nodes.size();cerr<<"depth "<<depth<<" labels "<<nodes.size()<<" live "<<nodes.size()-retired<<" comparisons "<<comparisons<<"\n";}if(!nodes[k].live)continue;int p=nodes[k].p;auto r=nodes[k].r;for(int ei:adj[p]){auto&e=es[ei];bool ok=true;for(int i=0;i<m;i++)if(e.in[i]>r[i])ok=false;for(int j=0;j<5;j++)if(e.mi[j]>r[m+j])ok=false;if(!ok)continue;vector<int>rr(d);for(int i=0;i<m;i++)rr[i]=min(cap,r[i]-e.in[i]+e.out[i]);for(int j=0;j<5;j++){rr[m+j]=r[m+max(0,j-e.c)];if(j<=e.c)rr[m+j]=max(rr[m+j],e.H);}add(e.t,rr,k,ei);if(nodes.size()>=limit){cout<<"status CAP labels "<<nodes.size()<<" depth "<<depth<<"\n";return 0;}if(hit>=0)break;}}
if(hit<0){cout<<"status NO_LOSSY_WITNESS labels "<<nodes.size()<<" live "<<nodes.size()-retired<<" depth "<<depth<<"\n";return 0;}cout<<"status PETRI_WITNESS labels "<<nodes.size()<<" depth "<<depth<<" saturation "<<cap<<"\n";vector<int>path;for(int u=hit;u>=0;u=nodes[u].parent)path.push_back(u);reverse(path.begin(),path.end());vector<int>actual(d);cout<<"start "<<nodes[path[0]].p<<"\n";for(int u:path){auto&n=nodes[u];if(n.parent<0)continue;auto&e=es[n.edge];cout<<"EDGE "<<n.edge<<" "<<e.f<<" "<<e.t<<" "<<e.a;for(int x:actual)cout<<" "<<x;cout<<"\n";for(int i=0;i<m;i++){assert(actual[i]>=e.in[i]);actual[i]+=e.out[i]-e.in[i];}vector<int>old=actual;for(int j=0;j<5;j++){assert(old[m+j]>=e.mi[j]);actual[m+j]=old[m+max(0,j-e.c)];if(j<=e.c)actual[m+j]=max(actual[m+j],e.H);}}bool ok=false;for(auto&g:goals[nodes[hit].p])if(le(g,actual))ok=true;assert(ok);cout<<"goal "<<nodes[hit].p;for(int x:actual)cout<<" "<<x;cout<<"\n";}
